import{_ as d,o as a,c as e,ag as r}from"./chunks/framework.CtWPcAmt.js";const b=JSON.parse('{"title":"2. 新手决策路径","description":"AI Agent 零基础教程","frontmatter":{"title":"2. 新手决策路径","description":"AI Agent 零基础教程","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"selection/02-decision-path.md","filePath":"selection/02-decision-path.md","lastUpdated":null}'),o={name:"selection/02-decision-path.md"};function s(n,t,l,i,p,h){return a(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="_2-新手决策路径" tabindex="-1">2. 新手决策路径 <a class="header-anchor" href="#_2-新手决策路径" aria-label="Permalink to &quot;2. 新手决策路径&quot;">​</a></h1><blockquote><p>目标：从「不知道装哪款」走到「先试用 1–2 款」</p><p>方法：四步过滤，每步只回答一个问题。全程不需要理解模型参数。</p></blockquote><h2 id="第-1-步-硬约束过滤-先排除「不能用的」" tabindex="-1">第 1 步：硬约束过滤（先排除「不能用的」） <a class="header-anchor" href="#第-1-步-硬约束过滤-先排除「不能用的」" aria-label="Permalink to &quot;第 1 步：硬约束过滤（先排除「不能用的」）&quot;">​</a></h2><p>回答四个问题，任一为「否」即排除该产品：</p><table tabindex="0"><thead><tr><th>问题</th><th>排除条件举例</th></tr></thead><tbody><tr><td>官方服务覆盖我的地区吗？</td><td>海外产品在中国大陆不可用/不稳定</td></tr><tr><td>我能注册、登录、付费吗？</td><td>无对应支付方式、注册受限</td></tr><tr><td>我的资料允许交给它处理吗？</td><td>公司/组织禁止上传，或我对隐私敏感</td></tr><tr><td>账号中断我能承受吗？</td><td>订阅中断意味着能力+历史同时不可用（Claude 阻断案例）</td></tr></tbody></table><blockquote><p><strong>Claude 特别提醒</strong>：作者在教程写作期间账号被封，能力无法进入统一任务。如果你对 Claude 感兴趣，第 1 步就是做账号可用性检查；<strong>能力判断和账号稳定性判断必须分开</strong>。</p></blockquote><p><strong>这一步通常已经能排除 2–3 款。</strong> 例如：不能接受资料出境的读者直接排除海外托管产品（Claude、Codex）；不想配置 API 的读者排除 BYOK 产品（ZCode、Hermes）。</p><h2 id="第-2-步-按任务类型选起点" tabindex="-1">第 2 步：按任务类型选起点 <a class="header-anchor" href="#第-2-步-按任务类型选起点" aria-label="Permalink to &quot;第 2 步：按任务类型选起点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我的主要任务</th><th>第一梯队（先试用）</th><th>对照梯队（备选）</th></tr></thead><tbody><tr><td>中文办公、文档、日常任务，零基础</td><td><strong>TraeWork CN、WorkBuddy</strong></td><td>QoderWork（扩展样本，未正式纳入）</td></tr><tr><td>代码项目为主，能接受 IDE</td><td><strong>Qoder CN、ZCode CN</strong></td><td>Codex</td></tr><tr><td>工作+代码+设计综合交付，已有订阅</td><td><strong>Codex</strong></td><td>WorkBuddy、TraeWork</td></tr><tr><td>高自主、模型自由、自托管</td><td><strong>Hermes Desktop</strong></td><td>ZCode</td></tr></tbody></table><p>判断依据（来自 2026-08-12 实测）：</p><ul><li>办公零基础：TraeWork 与 WorkBuddy 都是 0 人工介入、无需配置模型；TraeWork 三模式直观，WorkBuddy 变更可见性更好（+647/-0 diff）——两款都值得试，二选一靠第 3 步；</li><li>代码优先：Qoder 最快最省（2:00/¥0.25）但存在越权读取，ZCode 变更透明最强但要配置模型；Codex 是托管路径里综合一致性最佳、审阅支持提交推送；</li><li>极客路线：Hermes 是唯一有真实自动恢复实证的产品，四视图最灵活；代价是 Provider/API/环境配置与维护责任都在自己身上。</li></ul><h2 id="第-3-步-用偏好卡出胜负" tabindex="-1">第 3 步：用偏好卡出胜负 <a class="header-anchor" href="#第-3-步-用偏好卡出胜负" aria-label="Permalink to &quot;第 3 步：用偏好卡出胜负&quot;">​</a></h2><p>在第 2 步的第一梯队内，回答三组偏好问题：</p><table tabindex="0"><thead><tr><th>偏好问题</th><th>答案倾向</th><th>指向</th></tr></thead><tbody><tr><td>成本要在客户端直接可见吗？</td><td>要</td><td>Qoder（展示人民币）、TraeWork/WorkBuddy（展示积分/Credits）</td></tr><tr><td>数据边界敏感吗？「无弹窗」能接受吗？</td><td>非常敏感</td><td>Codex、ZCode、TraeWork、WorkBuddy（本轮未越权）</td></tr><tr><td>变更要逐文件核对吗？</td><td>要</td><td>ZCode（增删统计最细）、Codex、WorkBuddy</td></tr><tr><td>接受学习配置吗？</td><td>不接受</td><td>托管路径；排除 BYOK</td></tr><tr><td>要「审阅后直接提交推送」吗？</td><td>要</td><td>Codex（实测支持）</td></tr></tbody></table><p>如果第一梯队两款仍然分不出，就都试用（第 4 步用真实任务定胜负）。</p><h2 id="第-4-步-用真实任务试用并记录" tabindex="-1">第 4 步：用真实任务试用并记录 <a class="header-anchor" href="#第-4-步-用真实任务试用并记录" aria-label="Permalink to &quot;第 4 步：用真实任务试用并记录&quot;">​</a></h2><p>复制「个人选择卡」（<code>docs/10-selection-matrix.md</code> 第 4 节），然后用<strong>你自己的真实任务</strong>复测，不要用演示任务：</p><ol><li><strong>选 1 个真实小任务</strong>（15–30 分钟能完成，如整理一份周报素材）；</li><li>逐款完成，记录：总用时、人工介入次数、权限弹窗次数、产物是否一次通过、<strong>你是否看得懂它改了什么</strong>；</li><li>用下面的「试用记录表」固定证据，7 天后回来对比再决定是否付费。</li></ol><table tabindex="0"><thead><tr><th>记录项</th><th>产品 A</th><th>产品 B</th></tr></thead><tbody><tr><td>产品与版本 / 模式与模型</td><td></td><td></td></tr><tr><td>任务名称</td><td></td><td></td></tr><tr><td>总用时</td><td></td><td></td></tr><tr><td>人工介入次数及原因</td><td></td><td></td></tr><tr><td>权限确认次数</td><td></td><td></td></tr><tr><td>产物是否一次通过</td><td></td><td></td></tr><tr><td>变更/差异是否看得懂</td><td></td><td></td></tr><tr><td>本轮消耗（单位写清楚）</td><td></td><td></td></tr><tr><td>我能否独立恢复失败</td><td></td><td></td></tr></tbody></table><blockquote><p>成本记录务必写单位：<code>Credits</code>、<code>积分</code>、<code>¥</code>、<code>API 账单</code>——它们不可互相换算，只和自己比。</p></blockquote><h2 id="决策路径总览-一图流" tabindex="-1">决策路径总览（一图流） <a class="header-anchor" href="#决策路径总览-一图流" aria-label="Permalink to &quot;决策路径总览（一图流）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第1步 硬约束过滤 ──排除：地区/账号/支付/合规不可用者（含 Claude 先做可用性检查）</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>第2步 按任务类型 ──办公→TraeWork/WorkBuddy｜代码→Qoder/ZCode/Codex｜综合→Codex｜极客→Hermes</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>第3步 偏好定胜负 ──成本可见/边界敏感/变更核对/拒绝配置/审阅提交 各取所需</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>第4步 真实任务试用 ──记录六项指标 → 7 天后对比 → 决定是否付费</span></span></code></pre></div><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>用了两天发现「好像不如别人说的好」</td><td>用演示任务或别人的任务测的</td><td>换成自己的真实任务重测</td></tr><tr><td>两款都挺好，不知道选哪个</td><td>缺少固定记录</td><td>用试用记录表逐项打分，不要凭感觉</td></tr><tr><td>看总分选了「第一名」</td><td>误信了不存在的排名</td><td>回到 1.6：四种成本单位、两种路径、单一任务集，任何总分都不可比</td></tr><tr><td>换模型/换配置后体验大变</td><td>把 BYOK 结果当成了产品能力</td><td>对照 1.3 测试条件，确认你复现的是同一条路径</td></tr><tr><td>Claude 账号被封后不知所措</td><td>没做第 1 步可用性检查</td><td>先查地区/账号/支付，再决定是否投入</td></tr></tbody></table>`,24)])])}const u=d(o,[["render",s]]);export{b as __pageData,u as default};
